#include "coh_proficiencies.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>
static unsigned long long checks,cuts,mutations,cancellations;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"proficiency check %d: %s\n",__LINE__,#x);exit(1);}}while(0)
typedef struct{const unsigned char*d;size_t dn;const unsigned char*i;size_t in;unsigned status;const uint32_t*words;const unsigned char*text;const uint32_t*meta;unsigned count,id_count;}Fixture;
#include "fixtures.h"
typedef struct{unsigned calls;CohStatus status;unsigned fail_at;}Digest;
typedef struct{unsigned calls,stop;}Cancel;
static CohStatus digest(void*p,CohBytes b,uint8_t out[32]){Digest*d=p;d->calls++;SHA256(b.data,b.size,out);return d->fail_at&&d->calls!=d->fail_at?COH_OK:d->status;}
static int cancelled(void*p){Cancel*c=p;c->calls++;return c->stop&&c->calls==c->stop;}
static CohProficiencyDictionary out,before,saved;
static CohProficiencyWorkspace work;
static uint8_t hashes[2][32];static Digest ctx;static Cancel stop;
static CohCostumeImportDigest provider={digest,&ctx,sizeof(ctx),4096};
static CohProficiencyControl control={{cancelled,&stop},sizeof(stop),256};
static CohStatus read_input(CohBytes d,CohBytes i,size_t budget,size_t retained){memset(&out,0xa5,sizeof(out));before=out;CohStatus s=coh_proficiencies_read(d,i,1,(const uint8_t(*)[32])hashes,&provider,&control,&out,&work,budget,retained);if(s!=COH_OK)CHECK(!memcmp(&out,&before,sizeof(out)));return s;}
static CohStatus read_fixture(const Fixture*v){return read_input((CohBytes){v->d,v->dn},(CohBytes){v->i,v->in},COH_PROFICIENCY_RAM_MAX,0);}
static void fixture(const Fixture*v){SHA256(v->d,v->dn,hashes[0]);SHA256(v->i,v->in,hashes[1]);ctx=(Digest){0,COH_OK,0};stop=(Cancel){0,0};CHECK(read_fixture(v)==(CohStatus)v->status);if(v->status)return;CHECK(ctx.calls==2&&out.complete&&!out.runtime_generation&&!out.actor_authority&&out.provenance==1);CHECK(out.count==v->count&&out.id_count==v->id_count&&out.max_id==v->words[1]&&out.slot_count==v->words[2]);CHECK(!memcmp(out.sha256,hashes,64));const unsigned char*t=v->text;const uint32_t*m=v->meta;unsigned active=0;
 for(unsigned i=0;i<v->count;i++){CohProficiency*e=&out.entries[i];for(unsigned k=0;k<5;k++){CohProficiencyText x=e->fields[k];size_t n=strlen((const char*)t);CHECK(x.size==n&&!memcmp(out.text+x.offset,t,n+1));t+=n+1;}CHECK((uint32_t)e->origin==*m++);CHECK((uint32_t)e->rarity==*m++);CHECK((uint32_t)e->id==v->words[4+2*i]&&e->active==v->words[5+2*i]);active+=e->active;CohProficiencyText x=e->fields[0];char upper[260];for(unsigned j=0;j<x.size;j++){unsigned c=(unsigned char)out.text[x.offset+j];upper[j]=(char)(c>='a'&&c<='z'?c-32:c);}uint32_t row=999;CHECK(coh_proficiencies_find(&out,(CohBytes){(const uint8_t*)upper,x.size},&row)==COH_OK);CHECK(out.entries[row].active);uint32_t rev=999;if(e->active){CohStatus s=coh_proficiencies_join(&out,(CohBytes){(const uint8_t*)upper,x.size},(uint32_t)e->id,&rev);CHECK(s==(out.slots[e->id]==row+1?COH_OK:COH_NOT_FOUND));if(s==COH_OK)CHECK(rev==row);else CHECK(rev==999);}}
 CHECK(out.active_count==active);for(unsigned i=0;i<v->id_count;i++){CHECK((uint32_t)out.id_rows[i].id==*m++);CohProficiencyText x=out.id_rows[i].name;size_t n=strlen((const char*)t);CHECK(x.size==n&&!memcmp(out.text+x.offset,t,n+1));t+=n+1;uint32_t ir=999;CohStatus is=coh_proficiencies_id_find(&out,(CohBytes){(const uint8_t*)out.text+x.offset,x.size},&ir);uint32_t a=v->words[4+2*v->count+out.slot_count+2*i];CHECK(is==(a?COH_OK:COH_NOT_FOUND)&&ir==(a?a-1:999));ir=999;is=coh_proficiencies_id_name(&out,(uint32_t)out.id_rows[i].id,&ir);uint32_t b=v->words[5+2*v->count+out.slot_count+2*i];CHECK(is==(b?COH_OK:COH_NOT_FOUND)&&ir==(b?b-1:999));}
 for(unsigned i=0;i<out.slot_count;i++){CHECK(out.slots[i]==v->words[4+2*v->count+i]);uint32_t row=999;CHECK(coh_proficiencies_by_id(&out,i,&row)==(out.slots[i]?COH_OK:COH_NOT_FOUND));CHECK(row==(out.slots[i]?out.slots[i]-1:999));}
 uint32_t row=999;CHECK(coh_proficiencies_by_id(&out,UINT32_MAX,&row)==COH_NOT_FOUND&&row==999);CHECK(coh_proficiencies_find(&out,(CohBytes){(const uint8_t*)"unknown_missing",15},&row)==COH_NOT_FOUND&&row==999);CHECK(coh_proficiencies_find(&out,(CohBytes){(const uint8_t*)"\xff",1},&row)==COH_UNSUPPORTED&&row==999);CHECK(coh_proficiencies_find(&out,(CohBytes){(const uint8_t*)"Alpha",5},&out.count)==COH_INVALID);CHECK(coh_proficiencies_by_id(&out,1,(uint32_t*)((char*)&row+1))==COH_INVALID);
}
int main(void){for(unsigned i=0;i<sizeof(fixtures)/sizeof(fixtures[0]);i++)fixture(&fixtures[i]);const Fixture*v=&fixtures[0];fixture(v);saved=out;unsigned polls=stop.calls;
 for(unsigned n=1;n<=polls;n++){stop=(Cancel){0,n};CHECK(read_fixture(v)==COH_CANCELLED);CHECK(stop.calls==n);cancellations++;}stop=(Cancel){0,0};
 for(unsigned side=0;side<2;side++){size_t n=side?v->in:v->dn;const uint8_t*src=side?v->i:v->d;uint8_t*copy=malloc(n+1);CHECK(copy);for(size_t k=1;k<n;k++){ctx.calls=0;CHECK(read_input((CohBytes){v->d,side?v->dn:k},(CohBytes){v->i,side?k:v->in},COH_PROFICIENCY_RAM_MAX,0)!=COH_OK);CHECK(!ctx.calls);cuts++;}for(size_t k=0;k<n;k++){memcpy(copy,src,n);copy[k]^=255;CHECK(read_input((CohBytes){side?v->d:copy,v->dn},(CohBytes){side?copy:v->i,v->in},COH_PROFICIENCY_RAM_MAX,0)!=COH_OK);mutations++;}memcpy(copy,src,n);copy[n]=0;CHECK(read_input((CohBytes){side?v->d:copy,side?v->dn:n+1},(CohBytes){side?copy:v->i,side?n+1:v->in},COH_PROFICIENCY_RAM_MAX,0)!=COH_OK);free(copy);}
 fixture(v);size_t minimum=COH_PROFICIENCY_STACK_RESERVE+v->dn+v->in+sizeof(hashes)+sizeof(provider)+sizeof(control)+sizeof(out)+sizeof(work)+sizeof(ctx)+sizeof(stop)+provider.scratch_reserve+control.scratch_reserve;CHECK(read_input((CohBytes){v->d,v->dn},(CohBytes){v->i,v->in},minimum,0)==COH_OK);CHECK(read_input((CohBytes){v->d,v->dn},(CohBytes){v->i,v->in},minimum-1,0)==COH_LIMIT);CHECK(read_input((CohBytes){v->d,v->dn},(CohBytes){v->i,v->in},COH_PROFICIENCY_RAM_MAX,SIZE_MAX)==COH_LIMIT);provider.scratch_reserve=SIZE_MAX;CHECK(read_fixture(v)==COH_LIMIT);provider.scratch_reserve=4096;control.scratch_reserve=SIZE_MAX;CHECK(read_fixture(v)==COH_LIMIT);control.scratch_reserve=256;
 ctx.status=COH_IO;CHECK(read_fixture(v)==COH_IO);ctx.calls=0;ctx.fail_at=2;CHECK(read_fixture(v)==COH_IO&&ctx.calls==2);ctx.status=COH_OK;ctx.fail_at=0;hashes[0][0]^=1;CHECK(read_fixture(v)==COH_STATE);hashes[0][0]^=1;memset(hashes,0,sizeof(hashes));CHECK(read_fixture(v)==COH_STATE);SHA256(v->d,v->dn,hashes[0]);SHA256(v->i,v->in,hashes[1]);
 CHECK(coh_proficiencies_read((CohBytes){v->d,v->dn},(CohBytes){v->i,v->in},1,(const uint8_t(*)[32])hashes,&provider,&control,&out,(CohProficiencyWorkspace*)&out,COH_PROFICIENCY_RAM_MAX,0)==COH_INVALID);
 void*prior=provider.context;size_t bytes=provider.context_bytes;provider.context=&out;provider.context_bytes=1;CHECK(read_fixture(v)==COH_INVALID);provider.context=prior;provider.context_bytes=bytes;prior=control.cancel.context;bytes=control.context_bytes;control.cancel.context=&out;control.context_bytes=1;CHECK(read_fixture(v)==COH_INVALID);control.cancel.context=prior;control.context_bytes=bytes;
 CHECK(coh_proficiencies_read((CohBytes){v->d,v->dn},(CohBytes){v->d,v->dn},1,(const uint8_t(*)[32])hashes,&provider,&control,&out,&work,COH_PROFICIENCY_RAM_MAX,0)==COH_INVALID);
 CHECK(coh_proficiencies_read((CohBytes){v->d,v->dn},(CohBytes){v->i,v->in},1,(const uint8_t(*)[32])&out,&provider,&control,&out,&work,COH_PROFICIENCY_RAM_MAX,0)==COH_INVALID);
 prior=control.cancel.context;bytes=control.context_bytes;control.cancel.context=provider.context;control.context_bytes=provider.context_bytes;CHECK(read_fixture(v)==COH_INVALID);control.cancel.context=prior;control.context_bytes=bytes;
 fixture(v);uint32_t badrow=999;out.slots[1]=out.count+1;CHECK(coh_proficiencies_by_id(&out,1,&badrow)==COH_STATE&&badrow==999);out=saved;out.entries[0].id=999;CHECK(coh_proficiencies_by_id(&out,1,&badrow)==COH_STATE&&badrow==999);
 fixture(v);uint8_t*dc=malloc(v->dn),*ic=malloc(v->in);CHECK(dc&&ic);memcpy(dc,v->d,v->dn);memcpy(ic,v->i,v->in);CHECK(read_input((CohBytes){dc,v->dn},(CohBytes){ic,v->in},COH_PROFICIENCY_RAM_MAX,0)==COH_OK);memset(dc,0,v->dn);memset(ic,0,v->in);free(dc);free(ic);CHECK(!memcmp(&out,&saved,sizeof(out)));uint32_t row=99;CHECK(coh_proficiencies_by_id(&out,1,&row)==COH_OK);
 printf("{\"checks\":%llu,\"fixtures\":%zu,\"cuts\":%llu,\"mutations\":%llu,\"cancellations\":%llu,\"owner_bytes\":%zu,\"workspace_bytes\":%zu,\"control_bytes\":%zu,\"minimum_authentic_budget\":%zu,\"heap_allocations_in_reader\":0,\"runtime_generation\":false,\"actor_authority\":false}\n",checks,sizeof(fixtures)/sizeof(fixtures[0]),cuts,mutations,cancellations,sizeof(out),sizeof(work),sizeof(control),minimum);return 0;}
